"""Build a self-contained, offline icon review page."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
icons=json.loads((ROOT/'manifest.json').read_text())
data=[]
for icon in icons:
    row=dict(icon)
    for name,key in [('banner','svg'),('square','square_svg')]:
        row[name]=(ROOT/icon[key]).read_text().split('?>',1)[-1].strip()
    data.append(row)
payload=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>柔光电视图标</title>
<style>
:root{color-scheme:dark;--bg:#101621;--fg:#edf2f8;--muted:#a4b0c0;--line:#344051;--control:#1c2634;--focus:#9ad4cb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.5 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif;padding:32px 4vw 60px}body.light{color-scheme:light;--bg:#edf0f3;--fg:#1c2838;--muted:#536171;--line:#bac4ce;--control:#fff;--focus:#347f81}header{max-width:1840px;margin:0 auto 30px}h1{font-size:30px;font-weight:600;letter-spacing:.02em;margin:0 0 7px}.intro{color:var(--muted);margin:0 0 24px}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,input{font:inherit;color:var(--fg);background:var(--control);border:1px solid var(--line);border-radius:10px;min-height:44px;padding:8px 15px}button{cursor:pointer}button[aria-pressed=true]{border-color:var(--focus)}button:focus-visible,input:focus-visible,.tile:focus-visible{outline:3px solid var(--focus);outline-offset:5px}input{width:300px;max-width:100%}.status{margin-left:auto;color:var(--muted);font-size:14px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(252px,1fr));gap:28px 24px;max-width:1840px;margin:auto}.tile{border-radius:18px;min-width:0;outline:none}.art{aspect-ratio:16/9;border-radius:20px;overflow:hidden;box-shadow:0 6px 18px #0002}.art svg{width:100%;height:100%;display:block}.meta{display:flex;align-items:baseline;justify-content:space-between;gap:8px;margin:10px 3px 0}.label{font-size:16px;font-weight:500}.category{color:var(--muted);font-size:11px;white-space:nowrap}.square .art{aspect-ratio:1;border-radius:24%;box-shadow:none}.small .grid{grid-template-columns:repeat(auto-fill,160px);justify-content:start;gap:24px}.small .label{font-size:13px}.small .category{display:none}.small .art{border-radius:10px}.empty{color:var(--muted);padding:36px 0}footer{max-width:1840px;margin:36px auto 0;color:var(--muted);font-size:13px}.tile:focus-visible .art{filter:brightness(1.035)}@media(max-width:640px){body{padding:22px 18px 40px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 14px}h1{font-size:25px}.category{display:none}.status{margin-left:0}input{width:100%}.label{font-size:13px}.art{border-radius:14px}.small .grid{grid-template-columns:repeat(2,minmax(0,160px))}}
</style></head><body><header><h1>柔光电视图标</h1><p class="intro">轻微立体、柔和品牌色。查看整套图标，也可以切换到小尺寸检查辨识度。</p><div class="toolbar"><input id="search" type="search" aria-label="搜索应用" placeholder="搜索应用或类别"><button id="format" aria-pressed="false">切换方形</button><button id="theme" aria-pressed="false">浅色背景</button><button id="size" aria-pressed="false">小尺寸</button><span class="status" id="count" aria-live="polite"></span></div></header><main id="grid" class="grid" aria-label="图标预览"></main><footer>Tab 键聚焦，方向键移动。横幅适用于电视桌面；方形素材适用于其他入口。</footer><script>
const data=__ICONS__;let square=false,small=false;const grid=document.querySelector('#grid');
function render(){const q=document.querySelector('#search').value.trim().toLowerCase();const items=data.filter(x=>[x.id,x.label,x.category,...(x.aliases||[])].join(' ').toLowerCase().includes(q));grid.replaceChildren();for(const item of items){const el=document.createElement('article');el.className='tile';el.tabIndex=0;el.setAttribute('aria-label',item.label);const art=document.createElement('div');art.className='art';art.innerHTML=item[square?'square':'banner'];const meta=document.createElement('div');meta.className='meta';const label=document.createElement('span');label.className='label';label.textContent=item.label;const category=document.createElement('span');category.className='category';category.textContent=item.category;meta.append(label,category);el.append(art,meta);grid.append(el);}if(!items.length){const el=document.createElement('p');el.className='empty';el.textContent='没有匹配的图标';grid.append(el);}document.querySelector('#count').textContent=items.length+' / '+data.length+' 枚';}
document.querySelector('#search').addEventListener('input',render);
document.querySelector('#format').onclick=e=>{square=!square;document.body.classList.toggle('square',square);e.currentTarget.textContent=square?'切换横幅':'切换方形';e.currentTarget.setAttribute('aria-pressed',square);render();};
document.querySelector('#theme').onclick=e=>{const light=document.body.classList.toggle('light');e.currentTarget.textContent=light?'深色背景':'浅色背景';e.currentTarget.setAttribute('aria-pressed',light);};
document.querySelector('#size').onclick=e=>{small=!small;document.body.classList.toggle('small',small);e.currentTarget.textContent=small?'正常尺寸':'小尺寸';e.currentTarget.setAttribute('aria-pressed',small);};
grid.addEventListener('keydown',e=>{if(!e.key.startsWith('Arrow'))return;const cards=[...grid.querySelectorAll('.tile')],index=cards.indexOf(document.activeElement);if(index<0)return;e.preventDefault();const cols=getComputedStyle(grid).gridTemplateColumns.split(' ').length;const step={ArrowRight:1,ArrowLeft:-1,ArrowDown:cols,ArrowUp:-cols}[e.key];cards[Math.max(0,Math.min(cards.length-1,index+step))].focus();});render();
</script></body></html>'''
(ROOT/'preview.html').write_text(html.replace('__ICONS__',payload))
print('Built offline preview for',len(data),'icons.')
